<?php require '../config.php';require_admin();$users=db()->query('SELECT COUNT(*) total FROM users')->fetch_assoc()['total'];$products=db()->query('SELECT COUNT(*) total FROM products WHERE is_active=1')->fetch_assoc()['total'];$orders=db()->query("SELECT COUNT(*) total FROM orders WHERE status='paid'")->fetch_assoc()['total'];$revenue=db()->query("SELECT COALESCE(SUM(total),0) total FROM orders WHERE status='paid'")->fetch_assoc()['total'];$recent=db()->query('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC LIMIT 8');page_start('Admin dashboard'); ?><section class="section-space"><div class="container"><div class="d-flex justify-content-between align-items-end mb-5"><div><div class="eyebrow">Operations</div><h1 class="display-5 mb-0">Good morning, <?= e(current_user()['name']) ?>.</h1></div><a class="btn btn-dark btn-rounded" href="products.php">Manage products →</a></div><div class="row g-3 mb-5"><div class="col-md-3"><div class="stat"><div class="text-muted small">Revenue</div><div class="h3 mb-0"><?= money((float)$revenue) ?></div></div></div><div class="col-md-3"><div class="stat"><div class="text-muted small">Paid orders</div><div class="h3 mb-0"><?= $orders ?></div></div></div><div class="col-md-3"><div class="stat"><div class="text-muted small">Active products</div><div class="h3 mb-0"><?= $products ?></div></div></div><div class="col-md-3"><div class="stat"><div class="text-muted small">Registered users</div><div class="h3 mb-0"><?= $users ?></div></div></div></div><h2 class="h4 mb-3">Recent orders</h2><div class="bg-white rounded-3 p-3 table-responsive"><table class="table align-middle"><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Status</th><th>Total</th></tr></thead><tbody><?php while($order=$recent->fetch_assoc()): ?><tr><td>#<?= $order['id'] ?></td><td><?= e($order['name']) ?></td><td><?= date('M j, Y',strtotime($order['created_at'])) ?></td><td><?= e($order['status']) ?></td><td><?= money((float)$order['total']) ?></td></tr><?php endwhile; ?></tbody></table></div></div></section><?php page_end(); ?>